DROP PROCEDURE IF EXISTS l22_total;
DELIMITER //
CREATE PROCEDURE l22_total(IN preco DECIMAL(10,2),IN quantidade INT)
SQL SECURITY INVOKER
BEGIN
 IF preco IS NULL OR preco<0 OR quantidade IS NULL OR quantidade<1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Entrada invalida';
 END IF;
 SELECT preco*quantidade AS total;
END//
DELIMITER ;
CALL l22_total(12.50,3);
DROP PROCEDURE l22_total;

